On Tue, Aug 04, 2026 at 06:56:05PM -0500, Kim Phillips wrote:
...
> @@ -2297,13 +2299,26 @@ static void __init spectre_v2_apply_mitigation(void)
>  	if (spectre_v2_enabled == SPECTRE_V2_EIBRS && unprivileged_ebpf_enabled())
>  		pr_err(SPECTRE_V2_EIBRS_EBPF_MSG);
>  
> -	if (spectre_v2_in_ibrs_mode(spectre_v2_enabled)) {
> -		if (boot_cpu_has(X86_FEATURE_AUTOIBRS)) {
> +	/*
> +	 * head_64.S preserves EFER.AUTOIBRS across boot, so a kexec from a
> +	 * kernel that ran in AutoIBRS mode carries the bit into the new kernel.
> +	 * Explicitly set or clear it to match the selected mitigation, regardless
> +	 * of which mode is in effect.  The boot CPU does this before
> +	 * init_real_mode() snapshots EFER for the AP trampoline, so APs inherit
> +	 * the correct value too.
> +	 */
> +	if (boot_cpu_has(X86_FEATURE_AUTOIBRS)) {
> +		if (spectre_v2_in_eibrs_mode(spectre_v2_enabled))
>  			msr_set_bit(MSR_EFER, _EFER_AUTOIBRS);
> -		} else {
> -			x86_spec_ctrl_base |= SPEC_CTRL_IBRS;
> -			update_spec_ctrl(x86_spec_ctrl_base);
> -		}
> +		else
> +			msr_clear_bit(MSR_EFER, _EFER_AUTOIBRS);

Clearing the old kernel state should be done well before the mitigation
selection starts, below already does it for the SPEC_CTRL MSR:

  void __init cpu_select_mitigations(void)
  {
          /*
           * Read the SPEC_CTRL MSR to account for reserved bits which may
           * have unknown values. AMD64_LS_CFG MSR is cached in the early AMD
           * init code as it is not enumerated and depends on the family.
           */
          if (cpu_feature_enabled(X86_FEATURE_MSR_SPEC_CTRL)) {
                  rdmsrq(MSR_IA32_SPEC_CTRL, x86_spec_ctrl_base);

                  /*
                   * Previously running kernel (kexec), may have some controls
                   * turned ON. Clear them and let the mitigations setup below
                   * rediscover them based on configuration.
                   */
                  x86_spec_ctrl_base &= ~SPEC_CTRL_MITIGATIONS_MASK;
          }

> +	}
> +
> +	if (spectre_v2_in_ibrs_mode(spectre_v2_enabled) &&
> +	    !(boot_cpu_has(X86_FEATURE_AUTOIBRS) &&
> +	      spectre_v2_in_eibrs_mode(spectre_v2_enabled))) {
> +		x86_spec_ctrl_base |= SPEC_CTRL_IBRS;
> +		update_spec_ctrl(x86_spec_ctrl_base);
>  	}

Nit, I find this a bit confusing. IIUC when AutoIBRS is supported, you want
SPEC_CTRL[IBRS] to be set when legacy IBRS mitigation is deployed. If you
move MSR write down after legacy IBRS mode is set(KERNEL_IBRS), you can do:

          if (spectre_v2_in_ibrs_mode(spectre_v2_enabled)) {
                 if (boot_cpu_has(X86_FEATURE_AUTOIBRS) &&
                     !boot_cpu_has(X86_FEATURE_KERNEL_IBRS)) {    <---- just adding KERNEL_IBRS check to existing code
                          msr_set_bit(MSR_EFER, _EFER_AUTOIBRS);
                  } else {
                          x86_spec_ctrl_base |= SPEC_CTRL_IBRS;
                          update_spec_ctrl(x86_spec_ctrl_base);
                  }
          }

Otherwise, a comment explaining the intent would be helpful.

luka.gejak@linux.dev <luka.gejak@linux.dev> wrote:
> +
> +static void rtw_sdio_reschedule_tx_work(struct rtw_dev *rtwdev,
> +                                       struct rtw_sdio_work_data *work_data,
> +                                       unsigned long delay)
> +{
> +       struct rtw_sdio *rtwsdio = (struct rtw_sdio *)rtwdev->priv;
> +
> +       queue_delayed_work(rtwsdio->txwq, &work_data->work, delay);
>  }

Actually, I didn't request this wrapper by v4. (Also I don't prefer a
simple wrapper like this that hides kernel API).

(See below)

> 
>  static void rtw_sdio_tx_handler(struct work_struct *work)
>  {
>         struct rtw_sdio_work_data *work_data =
> -               container_of(work, struct rtw_sdio_work_data, work);
> +               container_of(to_delayed_work(work), struct rtw_sdio_work_data,
> +                            work);
>         struct rtw_sdio *rtwsdio;
>         struct rtw_dev *rtwdev;
> -       int limit, queue;
> +       int limit, queue, ret;
> +       bool rtl8723bs;
> 
>         rtwdev = work_data->rtwdev;
>         rtwsdio = (struct rtw_sdio *)rtwdev->priv;
> +       rtl8723bs = rtw_is_8723bs(rtwdev);
> 
>         if (!rtw_fw_feature_check(&rtwdev->fw, FW_FEATURE_TX_WAKE))
>                 rtw_sdio_deep_ps_leave(rtwdev);
> 
>         for (queue = RTK_MAX_TX_QUEUE_NUM - 1; queue >= 0; queue--) {
>                 for (limit = 0; limit < 1000; limit++) {
> -                       rtw_sdio_process_tx_queue(rtwdev, queue);
> +                       ret = rtw_sdio_process_tx_queue(rtwdev, queue);
> +                       if (ret > 0)
> +                               break;
> +
> +                       if (ret < 0) {
> +                               /*
> +                                * A page or output queue shortage and a failed
> +                                * skb expansion are both transient, and the
> +                                * frame is still queued, so come back for it.
> +                                * That matters once the queue can be stopped:
> +                                * a stopped queue is handed no further frames,
> +                                * so nothing else would kick this work item and
> +                                * the queue would stay stopped for good. The
> +                                * remaining errors cannot succeed on a retry
> +                                * and each log where they happen.
> +                                */
> +                               if (rtl8723bs &&
> +                                   (ret == -EBUSY || ret == -ENOMEM)) {
> +                                       rtw_sdio_reschedule_tx_work(rtwdev, work_data,
> +                                                                   RTW_SDIO_TX_RETRY_DELAY);
> +                                       return;
> +                               }
> +                               break;
> +                       }
> +
> +                       /*
> +                        * Restart from the highest priority queue after every
> +                        * management frame so the join sequence is not held up
> +                        * behind a data backlog.
> +                        */
> +                       if (rtl8723bs && queue == RTW_TX_QUEUE_MGMT) {
> +                               rtw_sdio_reschedule_tx_work(rtwdev, work_data, 0);
> +                               return;
> +                       }

I'd move this chunk you are adding to a function. I think it is just to
reschedule TX work for RTL8723BS for certain conditions, but explaining 
a lot of things (conditions) in common flow makes people hard to read
the flow. 

> 
>                         if (skb_queue_empty(&rtwsdio->tx_queue[queue]))
>                                 break;

Commit 5262eab9462a ("net: macb: allocate tieoff descriptor once across
device lifetime") moved macb_alloc_tieoff() and macb_free_tieoff() into
a CONFIG_OF block, breaking the build when it is disabled:

  drivers/net/ethernet/cadence/macb_main.c: In function 'macb_probe':
  drivers/net/ethernet/cadence/macb_main.c:5951:15: error: implicit declaration of function 'macb_alloc_tieoff' [-Wimplicit-function-declaration]
   5951 |         err = macb_alloc_tieoff(bp);
        |               ^~~~~~~~~~~~~~~~~
  drivers/net/ethernet/cadence/macb_main.c:5973:9: error: implicit declaration of function 'macb_free_tieoff' [-Wimplicit-function-declaration]
   5973 |         macb_free_tieoff(bp);
        |         ^~~~~~~~~~~~~~~~

Moving macb_alloc_tieoff() from its original positive does not appear to
be necessary, so move it and macb_free_tieoff() back out of the
CONFIG_OF block to clear up the error.

Fixes: 5262eab9462a ("net: macb: allocate tieoff descriptor once across device lifetime")
Signed-off-by: Nathan Chancellor <nathan@kernel.org>
---
This does not apply to net currently but I assume net will be fast
forwarded when net-next-7.3 is merged.
---
 drivers/net/ethernet/cadence/macb_main.c | 64 ++++++++++++++++----------------
 1 file changed, 32 insertions(+), 32 deletions(-)

diff --git a/drivers/net/ethernet/cadence/macb_main.c b/drivers/net/ethernet/cadence/macb_main.c
index 1476bce77f34..96a7e7777e62 100644
--- a/drivers/net/ethernet/cadence/macb_main.c
+++ b/drivers/net/ethernet/cadence/macb_main.c
@@ -2776,6 +2776,38 @@ static int macb_alloc(struct macb *bp)
 	return -ENOMEM;
 }
 
+static int macb_alloc_tieoff(struct macb *bp)
+{
+	/* Tieoff is a workaround in case HW cannot disable queues, for PM. */
+	if (bp->caps & MACB_CAPS_QUEUE_DISABLE)
+		return 0;
+
+	bp->rx_ring_tieoff = dma_alloc_coherent(&bp->pdev->dev,
+						macb_dma_desc_get_size(bp),
+						&bp->rx_ring_tieoff_dma,
+						GFP_KERNEL);
+	if (!bp->rx_ring_tieoff)
+		return -ENOMEM;
+
+	macb_set_addr(bp, bp->rx_ring_tieoff,
+		      MACB_BIT(RX_WRAP) | MACB_BIT(RX_USED));
+
+	bp->rx_ring_tieoff->ctrl = 0;
+
+	return 0;
+}
+
+static void macb_free_tieoff(struct macb *bp)
+{
+	if (!bp->rx_ring_tieoff)
+		return;
+
+	dma_free_coherent(&bp->pdev->dev, macb_dma_desc_get_size(bp),
+			  bp->rx_ring_tieoff,
+			  bp->rx_ring_tieoff_dma);
+	bp->rx_ring_tieoff = NULL;
+}
+
 static void gem_init_rx_ring(struct macb_queue *queue)
 {
 	queue->rx_tail = 0;
@@ -5507,38 +5539,6 @@ static int eyeq5_init(struct platform_device *pdev)
 	return ret;
 }
 
-static int macb_alloc_tieoff(struct macb *bp)
-{
-	/* Tieoff is a workaround in case HW cannot disable queues, for PM. */
-	if (bp->caps & MACB_CAPS_QUEUE_DISABLE)
-		return 0;
-
-	bp->rx_ring_tieoff = dma_alloc_coherent(&bp->pdev->dev,
-						macb_dma_desc_get_size(bp),
-						&bp->rx_ring_tieoff_dma,
-						GFP_KERNEL);
-	if (!bp->rx_ring_tieoff)
-		return -ENOMEM;
-
-	macb_set_addr(bp, bp->rx_ring_tieoff,
-		      MACB_BIT(RX_WRAP) | MACB_BIT(RX_USED));
-
-	bp->rx_ring_tieoff->ctrl = 0;
-
-	return 0;
-}
-
-static void macb_free_tieoff(struct macb *bp)
-{
-	if (!bp->rx_ring_tieoff)
-		return;
-
-	dma_free_coherent(&bp->pdev->dev, macb_dma_desc_get_size(bp),
-			  bp->rx_ring_tieoff,
-			  bp->rx_ring_tieoff_dma);
-	bp->rx_ring_tieoff = NULL;
-}
-
 static const struct macb_usrio_config mpfs_usrio = {
 	.tsu_source = 0,
 };

